        if (type != SDP_TYPE_SEQUENCE && type != SDP_TYPE_ALTERNATIVE)
            return ERROR_INVALID_PARAMETER;
        if (!(size_desc >= SDP_SIZE_DESC_NEXT_UINT8 && size_desc <= SDP_SIZE_DESC_NEXT_UINT32))
            return ERROR_INVALID_PARAMETER;

        stream++;
        if (!sdp_elem_read_var_size( stream, stream_size, &read, size_desc, &elems_size ))
            return ERROR_INVALID_PARAMETER;

        stream += read;
        stream_size -= read;
    }
    else
    {
        if (cursor < stream) return ERROR_INVALID_PARAMETER;
        if (cursor == (stream + stream_size)) return ERROR_NO_MORE_ITEMS;

        stream = cursor;
        stream_size = stream_size - (cursor - stream);
    }
    result = sdp_read_element_data( stream, stream_size, data, &read );
    if (result != ERROR_SUCCESS) return result;

    stream += read;
    TRACE( "handle=%p\n", stream );
    *handle = stream;
    return ERROR_SUCCESS;
}

{
    SIZE_T read = 0;

    TRACE( "(%p, %lu, %p)\n", stream, stream_size, data );

    if (stream == NULL || stream_size < sizeof( BYTE ) || data == NULL)
        return ERROR_INVALID_PARAMETER;

    return sdp_read_element_data( stream, stream_size, data, &read );
}

{
    HRESULT res = S_OK;
    HFDI hfdi;
    char *str, *end, *path = NULL, *name = NULL;

    TRACE("(%p, %s)\n", dest, debugstr_a(szCabName));

    hfdi = FDICreate(mem_alloc,
                     mem_free,
                     fdi_open,
                     fdi_read,
                     fdi_write,
                     fdi_close,
                     fdi_seek,
                     cpuUNKNOWN,
                     &dest->Error);

    if (!hfdi)
        return E_FAIL;

    if (GetFileAttributesA(dest->Destination) == INVALID_FILE_ATTRIBUTES)
    {
        res = S_OK;
        goto end;
    }

    /* split the cabinet name into path + name */
    str = HeapAlloc(GetProcessHeap(), 0, lstrlenA(szCabName)+1);
    if (!str)
    {
        res = E_OUTOFMEMORY;
        goto end;
    }
    lstrcpyA(str, szCabName);

    if ((end = strrchr(str, '\\')))
    {
        path = str;
        end++;
        name = HeapAlloc( GetProcessHeap(), 0, strlen(end) + 1 );
        if (!name)
        {
            res = E_OUTOFMEMORY;
            goto end;
        }
        strcpy( name, end );
        *end = 0;
    }
    else
    {
        name = str;
        path = NULL;
    }

    dest->FileSize = 0;

    if (!FDICopy(hfdi, name, path, 0,
         fdi_notify_extract, NULL, dest))
        res = HRESULT_FROM_WIN32(GetLastError());

end:
    HeapFree(GetProcessHeap(), 0, path);
    HeapFree(GetProcessHeap(), 0, name);
    FDIDestroy(hfdi);
    return res;
}

