            hr = IDirect3DTexture9_GetLevelDesc(texture, 0, &desc);
            if (FAILED(hr))
                break;

            fmt_desc = get_format_info(desc.Format);
            if (is_unknown_format(fmt_desc))
                return E_NOTIMPL;

            set_volume_struct(&size, desc.Width, desc.Height, 1);
            break;
        }

