{
    GpStatus stat;
    const struct image_codec *codec = NULL;

    TRACE("(%p,%s,%u)\n", image, debugstr_guid(dimensionID), frame);

    if (!image || !dimensionID)
        return InvalidParameter;
    if(!image_lock(image))
        return ObjectBusy;

    if (frame >= image->frame_count)
        WARN("requested frame %u, but image has only %u\n", frame, image->frame_count);
        /* rely on codec->select_func() to fail */

    if (image->type != ImageTypeBitmap && image->type != ImageTypeMetafile)
    {
        WARN("invalid image type %d\n", image->type);
        image_unlock(image);
        return InvalidParameter;
    }

    if (image->current_frame == frame)
    {
        image_unlock(image);
        return Ok;
    }

    if (!image->decoder)
    {
        TRACE("image doesn't have an associated decoder\n");
        image_unlock(image);
        return Ok;
    }

    /* choose an appropriate image decoder */
    stat = get_decoder_info_from_image(image, &codec);
    if (stat != Ok)
    {
        WARN("can't find decoder info\n");
        image_unlock(image);
        return stat;
    }

    stat = codec->select_func(image, frame);
    image_unlock(image);
    return stat;
}

{
    GpMatrix copy;
    REAL det;

    TRACE("(%s)\n", debugstr_matrix(matrix));

    if(!matrix)
        return InvalidParameter;

    /* optimize inverting simple scaling and translation matrices */
    if(matrix->matrix[1] == 0 && matrix->matrix[2] == 0)
    {
        if (matrix->matrix[0] != 0 && matrix->matrix[3] != 0)
        {
            matrix->matrix[4] = -matrix->matrix[4] / matrix->matrix[0];
            matrix->matrix[5] = -matrix->matrix[5] / matrix->matrix[3];
            matrix->matrix[0] = 1 / matrix->matrix[0];
            matrix->matrix[3] = 1 / matrix->matrix[3];

            return Ok;
        }
        else
            return InvalidParameter;
    }
    det = matrix_det(matrix);
    if (!(fabs(det) >= 1e-5))
        return InvalidParameter;

    det = 1 / det;

    copy = *matrix;
    /* store result */
    matrix->matrix[0] =   copy.matrix[3] * det;
    matrix->matrix[1] =  -copy.matrix[1] * det;
    matrix->matrix[2] =  -copy.matrix[2] * det;
    matrix->matrix[3] =   copy.matrix[0] * det;
    matrix->matrix[4] =  (copy.matrix[2]*copy.matrix[5]-copy.matrix[3]*copy.matrix[4]) * det;
    matrix->matrix[5] = -(copy.matrix[0]*copy.matrix[5]-copy.matrix[1]*copy.matrix[4]) * det;

    return Ok;
}

