{
    INT i, count;
    INT start = 0; /* position in reversed path */
    GpPathData revpath;

    TRACE("(%p)\n", path);

    if(!path)
        return InvalidParameter;

    count = path->pathdata.Count;

    if(count == 0) return Ok;

    revpath.Points = calloc(count, sizeof(GpPointF));
    revpath.Types  = calloc(count, sizeof(BYTE));
    revpath.Count  = count;
    if(!revpath.Points || !revpath.Types){
        free(revpath.Points);
        free(revpath.Types);
        return OutOfMemory;
    }

    for(i = 0; i < count; i++){
        /* find next start point */
        if(path->pathdata.Types[count-i-1] == PathPointTypeStart){
            INT j;
            for(j = start; j <= i; j++){
                /* copy points coordinate of subpath in reverse order */
                revpath.Points[j] = path->pathdata.Points[count-j-1];
                /* copy points type shifted by one (j + 1), as the first point type is always PathPointTypeStart */
                if (j < i)
                    revpath.Types[j + 1] = path->pathdata.Types[count - j - 1];
            }
            /* first point of subpath is always Start point */
            revpath.Types[start] = PathPointTypeStart;
            /* check if subpath contains more than 1 point */
            if(i-start > 1){
                /* add e.g. PathPointTypeCloseSubpath type to endpoint, if existing in original subpath */
                revpath.Types[i] |= path->pathdata.Types[count - start - 1] & ~PathPointTypePathTypeMask;
                /* remove e.g. PathPointTypeCloseSubpath type from second point */
                revpath.Types[start + 1] &= PathPointTypePathTypeMask;
            }
            else
                revpath.Types[i] = path->pathdata.Types[start];

            start = i+1;
        }
    }

    memcpy(path->pathdata.Points, revpath.Points, sizeof(GpPointF)*count);
    memcpy(path->pathdata.Types,  revpath.Types,  sizeof(BYTE)*count);

    free(revpath.Points);
    free(revpath.Types);

    return Ok;
}

{
    REAL cos_theta, sin_theta, rotate[6];

    TRACE("(%p, %.2f, %d)\n", debugstr_matrix(matrix), angle, order);

    if(!matrix)
        return InvalidParameter;

    angle = deg2rad(angle);
    cos_theta = cos(angle);
    sin_theta = sin(angle);

    rotate[0] = cos_theta;
    rotate[1] = sin_theta;
    rotate[2] = -sin_theta;
    rotate[3] = cos_theta;
    rotate[4] = 0.0;
    rotate[5] = 0.0;

    if(order == MatrixOrderAppend)
        matrix_multiply(matrix->matrix, rotate, matrix->matrix);
    else if (order == MatrixOrderPrepend)
        matrix_multiply(rotate, matrix->matrix, matrix->matrix);
    else
        return InvalidParameter;

    return Ok;
}

