    if (end_pos == pos) return (bitmap->Buffer[pos] | ~maskbits( start ) | maskbits( end )) == ~0u;

    if ((bitmap->Buffer[pos++] | ~maskbits( start )) != ~0u) return FALSE;
    while (pos < end_pos) if (bitmap->Buffer[pos++] != ~0u) return FALSE;
