            }
            i = MultiByteToWideChar(CP_ACP, 0, p, -1, NULL, 0);
            buffer = malloc(i * sizeof(WCHAR));
            if (!buffer)
            {
                i = 0;
                goto end;
            }
            MultiByteToWideChar(CP_ACP, 0, p, -1, buffer, i);
            filename = buffer;
        }

	i = lstrlenW(filename);
	if (!lpszwFile || !lLength) goto end;   /* needed buffer size */
	lstrcpynW(lpszwFile, filename, lLength);
	i = min(i, lLength - 1);
