  TRACE("(%s)\n", debugstr_a(path));

  if (!path) return;

  ext = PathFindExtensionA(path);
  if (ext == path || ext[-1] != ']') return;

  skip = ext - 2;
  while (skip > path && '0' <= *skip && *skip <= '9')
      skip--;

  if (skip > path && *skip == '[' && skip[-1] != '\\')
      memmove(skip, ext, strlen(ext) + 1);
}

