    if (info->cbSize != sizeof(*info))
    {
        RtlSetLastWin32Error( ERROR_INVALID_PARAMETER );
        return FALSE;
    }

    while ((status = get_shared_input( id, &lock, &input_shm )) == STATUS_PENDING)
    {
        info->flags          = 0;
        info->hwndActive     = wine_server_ptr_handle( input_shm->active );
        info->hwndFocus      = wine_server_ptr_handle( input_shm->focus );
        info->hwndCapture    = wine_server_ptr_handle( input_shm->capture );
        info->hwndMenuOwner  = wine_server_ptr_handle( input_shm->menu_owner );
        info->hwndMoveSize   = wine_server_ptr_handle( input_shm->move_size );
        info->hwndCaret      = wine_server_ptr_handle( input_shm->caret );
        info->rcCaret        = wine_server_get_rect( input_shm->caret_rect );
        if (input_shm->menu_owner) info->flags |= GUI_INMENUMODE;
        if (input_shm->move_size) info->flags |= GUI_INMOVESIZE;
        if (input_shm->caret) info->flags |= GUI_CARETBLINKING;
    }

    if (status)
    {
        info->flags = 0;
        info->hwndActive = 0;
        info->hwndFocus = 0;
        info->hwndCapture = 0;
        info->hwndMenuOwner = 0;
        info->hwndMoveSize = 0;
        info->hwndCaret = 0;
        memset( &info->rcCaret, 0, sizeof(info->rcCaret) );
    }

    return TRUE;
}

{
    struct object_lock lock = OBJECT_LOCK_INIT;
    const input_shm_t *input_shm;
    UINT64 keystate_serial = 0;
    BOOL ret = FALSE;
    SHORT retval = 0;
    NTSTATUS status;

    while ((status = get_shared_input( GetCurrentThreadId(), &lock, &input_shm )) == STATUS_PENDING)
    {
        ret = !!input_shm->keystate_lock; /* needs a request for sync_input_keystate if desktop keystate differs. */
        keystate_serial = input_shm->keystate_serial;
        retval = (signed char)(input_shm->keystate[vkey & 0xff] & 0x81);
    }

    if (!ret)
    {
        struct object_lock lock = OBJECT_LOCK_INIT;
        const desktop_shm_t *desktop_shm;

        while ((status = get_shared_desktop( &lock, &desktop_shm )) == STATUS_PENDING)
            ret = keystate_serial == desktop_shm->keystate_serial;
    }

    if (!ret) SERVER_START_REQ( get_key_state )
    {
        req->key = vkey;
        if (!wine_server_call( req )) retval = (signed char)(reply->state & 0x81);
    }
    SERVER_END_REQ;
    TRACE("key (0x%x) -> %x\n", vkey, retval);
    return retval;
}

{
    struct object_lock lock = OBJECT_LOCK_INIT;
    const input_shm_t *input_shm;
    NTSTATUS status;
    UINT i;

    TRACE("(%p)\n", state);

    while ((status = get_shared_input( GetCurrentThreadId(), &lock, &input_shm )) == STATUS_PENDING)
        memcpy( state, (const void *)input_shm->keystate, 256 );
    if (status) memset( state, 0, 256 );

    for (i = 0; i < 256; i++) state[i] &= 0x81;
    return TRUE;
}

