{
    unsigned int i;
    const WCHAR *s = string;
    WCHAR       *end;

    TRACE( "%s %p 0x%08lx\n", debugstr_w(string), time, reserved );

    if (!string || !time) return FALSE;

    /* Windows does this too */
    GetSystemTime( time );

    /*  Convert an RFC1123 time such as 'Fri, 07 Jan 2005 12:06:35 GMT' into
     *  a SYSTEMTIME structure.
     */

    while (*s && !iswalpha(*s) && !is_time_digit(*s)) s++;
    if (*s == '\0') return TRUE;
    time->wDayOfWeek = 7;

    if (iswalpha(*s))
    {
        if (s[1] == '\0' || s[2] == '\0') return TRUE;
        for (i = 0; i < 7; i++)
        {
            if (!wcsnicmp(WININET_wkday[i], s, 3))
            {
                time->wDayOfWeek = i;
                s += 3;
                break;
            }
        }
    }
    else if (is_time_digit(*s))
    {
        time->wDayOfWeek = wcstol(s, &end, 10);
        s = end;
    }
    if (time->wDayOfWeek > 6) return TRUE;

    while (*s && !iswalpha(*s) && !is_time_digit(*s)) s++;
    if (*s == '\0') return TRUE;
    if (is_time_digit(*s))
    {
        calc_day(time, &s);
        while (*s && !iswalpha(*s) && !is_time_digit(*s)) s++;
        if (calc_month(time, &s))
            return TRUE;
    }else
    {
        if (calc_month(time, &s))
            return TRUE;
        while (*s && !iswalpha(*s) && !is_time_digit(*s)) s++;
        calc_day(time, &s);
    }

    while (*s && !is_time_digit(*s)) s++;
    if (*s == '\0') return TRUE;
    if (is_time(s))
    {
        if (calc_time(time, &s))
            return TRUE;
        while (*s && !is_time_digit(*s)) s++;
        calc_year(time, &s);
    }else
    {
        if (calc_year(time, &s))
            return TRUE;
        while (*s && !is_time_digit(*s)) s++;
        calc_time(time, &s);
    }
    return TRUE;
}

